CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar UNIQUE,
  "password_hash" varchar,
  "user_name" varchar UNIQUE,
  "status" varchar,
  "role" varchar,
  "avatar_url" varchar,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "global_profiles" (
  "user_id" integer PRIMARY KEY,
  "full_name" varchar,
  "phone" varchar,
  "bio" text,
  "dob" date,
  "gender" varchar,
  "settings" json,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "global_identity_verifications" (
  "user_id" integer PRIMARY KEY,
  "citizen_id" varchar UNIQUE,
  "extracted_data" json,
  "verified_at" timestamp,
  "provider" varchar
);

CREATE TABLE "organizations" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "slug" varchar UNIQUE,
  "logo_url" varchar,
  "brand_config" json,
  "features_config" json,
  "programs" json,
  "majors" json,
  "status" varchar DEFAULT 'active',
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "organization_introductions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "orga_id" integer UNIQUE REFERENCES organizations(id) ON DELETE CASCADE,
  "content" text,
  "image_urls" json,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "organization_members" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" integer,
  "user_id" integer UNIQUE,
  "graduated_year" integer,
  "graduation_status" varchar,
  "program" varchar,
  "major" varchar,
  "verification_level" integer DEFAULT 0,
  "is_trusted_verifier" boolean DEFAULT false,
  "status" varchar DEFAULT 'active',
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "academic_records" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "member_id" integer,
  "student_code" varchar,
  "degree_type" varchar,
  "class_name" varchar,
  "start_year" integer,
  "graduated_year" integer,
  "status" varchar
);

CREATE TABLE "peer_verifications" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "target_member_id" integer,
  "verifier_member_id" integer,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "verification_requests" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "member_id" integer,
  "document_url" varchar,
  "document_type" varchar,
  "status" varchar,
  "admin_note" text,
  "reviewed_by_member_id" integer,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "events" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" integer,
  "creator_member_id" integer,
  "title" varchar,
  "description" text,
  "banner_url" varchar,
  "location" varchar,
  "start_time" timestamp,
  "end_time" timestamp,
  "registration_start_at" timestamp,
  "registration_end_at" timestamp,
  "max_capacity" integer,
  "interested_count" integer DEFAULT 0,
  "topic" varchar,
  "is_published" boolean DEFAULT false,
  "created_at" timestamp
);

CREATE TABLE "event_interests" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "event_id" integer,
  "member_id" integer,
  "created_at" timestamp
);

CREATE TABLE "event_tickets" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "event_id" integer,
  "member_id" integer,
  "guest_name" varchar,
  "guest_email" varchar,
  "guest_phone" varchar,
  "ticket_code" varchar UNIQUE,
  "status" varchar,
  "registered_at" timestamp,
  "checked_in_at" timestamp
);

CREATE TABLE "mentor_profiles" (
  "member_id" integer PRIMARY KEY,
  "current_job_title" varchar,
  "current_company" varchar,
  "bio" text,
  "rating_avg" decimal DEFAULT 0,
  "total_sessions" integer DEFAULT 0,
  "is_approved" boolean DEFAULT false,
  "cover_url" varchar,
  "default_meeting_link" varchar,
  "booking_window_settings" text,
  "extended_profile" text,
  "created_at" timestamp
);

CREATE TABLE "mentor_expertise" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mentor_member_id" integer,
  "topic" varchar,
  "years_experience" integer,
  "description" text,
  "category" varchar,
  "tag" varchar
);

CREATE TABLE "mentor_availabilities" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mentor_member_id" integer,
  "start_time" timestamp,
  "end_time" timestamp,
  "status" varchar DEFAULT 'Available'
);

CREATE TABLE "mentorship_sessions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "availability_id" integer,
  "mentee_member_id" integer,
  "status" varchar,
  "booking_note" text,
  "meeting_link" varchar,
  "session_type" varchar,
  "introduction" text,
  "description" text,
  "cv_url" varchar,
  "created_at" timestamp
);

CREATE TABLE "session_feedbacks" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "session_id" integer,
  "mentee_member_id" integer,
  "rating" integer,
  "comment" text,
  "is_public" boolean,
  "created_at" timestamp
);

CREATE TABLE "news" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" integer,
  "author_member_id" integer,
  "title" varchar,
  "slug" varchar,
  "content" text,
  "thumbnail_url" varchar,
  "topic" varchar,
  "is_hidden" boolean,
  "published_at" timestamp
);

CREATE TABLE "alumni_posts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" integer,
  "author_member_id" integer,
  "title" varchar,
  "slug" varchar,
  "content" text,
  "thumbnail_url" varchar,
  "topic" varchar,
  "is_hidden" boolean,
  "published_at" timestamp
);

CREATE TABLE "saved_items" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "member_id" integer,
  "item_type" varchar,
  "item_id" integer,
  "note" text,
  "saved_at" timestamp
);

CREATE TABLE "achievements" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "member_id" integer,
  "title" varchar,
  "description" text,
  "image_url" varchar,
  "awarded_date" date,
  "topic" varchar,
  "status" varchar
);

CREATE TABLE "jobs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" integer,
  "poster_member_id" integer,
  "is_referral" boolean DEFAULT false,
  "type" varchar,
  "title" varchar,
  "company_name" varchar,
  "location" varchar,
  "salary_range" varchar,
  "description" text,
  "how_to_apply" text,
  "deadline" date,
  "is_active" boolean,
  "created_at" timestamp
);

CREATE TABLE "learning_resources" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" integer,
  "uploader_member_id" integer,
  "title" varchar,
  "type" varchar,
  "link_url" varchar,
  "description" text,
  "created_at" timestamp
);

-- Thong tin cua quy
CREATE TABLE "funds" (
  "id" BIGSERIAL PRIMARY KEY,
  "organization_id" integer,
  --"manager_member_id" integer,
  "manager_name" varchar,  -- old: manager_member_id, 
  -- but in the figma file, i see the text field input for this, 
  -- and it is more concise as the manager may not be an alumni 
  "name" varchar,
  "logo_url" varchar,
  "fund_receiving_info_id" integer, -- khoa ngoai den fund_receiving_infos
  "description_short" text, -- dung de hien thi khi xem list view
  "description_full" text, -- dung de hien thi khi xem detail view
  "target_amount" decimal,
  "current_amount" decimal,
  "time_started" timestamp,
  "donor_count" integer DEFAULT 0, -- so luong donate, phuc vu frontend
  "status_id" integer,  -- khoa ngoai den fund_statuses
  "topic" varchar,
  "time_ended" timestamp
);

CREATE TABLE "fund_statuses" ( -- force to have as admin can add new status, mac dinh la co QUAN TRONG, VUNG SAU VUNG XA
  "id" SERIAL PRIMARY KEY,
  "name" varchar
);

CREATE TABLE "fund_receiving_infos" (
  "id" BIGSERIAL PRIMARY KEY,
  --"type" varchar,
  "account_number" varchar,
  "account_name" varchar,
  "bank_name" varchar, -- ma code dua tren payos
  -- "qr_code_url" varchar, generate QR dong nen se khong can cai nay
  "is_active" boolean  -- trang thai dang ki tren payos, neu chua dang ki thi = false
);

CREATE TABLE "fund_donations" (
  "id" BIGSERIAL PRIMARY KEY,
  "fund_id" integer,
  "donor_member_id" integer, -- nullable as if the donate person is guest
  "donor_name" varchar,
  "amount" decimal NOT NULL,
  "address" varchar,
  "phone" varchar,
  "email" varchar,
  "message" text,
  "status" varchar, -- enum: PENDING, SUCCESS, FAILED
  "created_at" timestamp
);

