--   "fund_id" integer,
--   "title" varchar,
--   "amount" decimal,
--   "expense_date" date,
--   "proof_document_url" varchar,
--   "created_at" timestamp
-- );

CREATE TABLE "notifications" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "member_id" integer,
  "title" varchar,
  "message" text,
  "is_read" boolean,
  "created_at" timestamp
);

CREATE TABLE "school_feedbacks" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" integer NOT NULL,
  "full_name" varchar,
  "phone" varchar,
  "email" varchar,
  "subject" varchar,
  "content" text NOT NULL,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "is_read" boolean DEFAULT false
);

CREATE TABLE "user_login_histories" (
  "id" BIGSERIAL PRIMARY KEY,
  "user_id" integer NOT NULL,
  "login_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "login_method" varchar,
  "login_ip" varchar,
  "user_agent" text
);

CREATE TABLE "user_notification_settings" (
  "user_id" integer PRIMARY KEY,
  "email_enabled" boolean DEFAULT true,
  "push_enabled" boolean DEFAULT true,
  "event_reminder_enabled" boolean DEFAULT true,
  "news_enabled" boolean DEFAULT true,
  "forum_reply_enabled" boolean DEFAULT true,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "forum_categories" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "parent_id" integer DEFAULT NULL,
  "organization_id" integer,
  "name" varchar,
  "description" text,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "forum_topics" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" integer,
  "title" varchar,
  "created_by_member_id" integer,
  "category_id" integer, 
  "view_count" integer DEFAULT 0,
  "is_locked" boolean DEFAULT false,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "forum_posts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "topic_id" integer,
  "author_member_id" integer,
  "content" text,
  "answer_to_post_id" integer,
  "is_banned" boolean DEFAULT false,
  "is_hidden" boolean DEFAULT false,
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "forum_post_reports" (
  "id" BIGSERIAL PRIMARY KEY,
  "post_id" integer NOT NULL,
  "reporter_member_id" integer NOT NULL,
  "reason" varchar,
  "description" text,
  "status" varchar DEFAULT 'PENDING',
  "reviewed_by_user_id" integer,
  "review_note" text,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "forum_post_reactions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "post_id" integer NOT NULL,
  "member_id" integer NOT NULL,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "forum_polls" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "topic_id" integer,
  "organization_id" integer,
  "created_by_member_id" integer,
  "title" varchar NOT NULL,
  "description" text,
  "allow_multiple_votes" boolean DEFAULT false,
  "is_active" boolean DEFAULT true,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "admin_audit_logs" (
  "id" BIGSERIAL PRIMARY KEY,
  "admin_user_id" integer NOT NULL,
  "target_user_id" integer,
  "action" varchar NOT NULL,
  "resource_type" varchar NOT NULL,
  "resource_id" varchar,
  "before_data" jsonb,
  "after_data" jsonb,
  "metadata" jsonb,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "forum_poll_options" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "poll_id" integer NOT NULL,
  "option_text" varchar NOT NULL,
  "vote_count" integer DEFAULT 0,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "forum_poll_votes" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "poll_id" integer NOT NULL,
  "poll_option_id" integer NOT NULL,
  "member_id" integer NOT NULL,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "chat_groups" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "type" varchar NOT NULL,                -- 'PRIVATE' hoặc 'GROUP'
  "title" varchar,                        -- tên group (null với PRIVATE)
  "created_by" integer NOT NULL,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "chat_group_members" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "group_id" integer NOT NULL,
  "member_id" integer NOT NULL,
  "role" varchar DEFAULT 'member',     -- 'owner' / 'admin' / 'member'
  "joined_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "chat_messages" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "group_id" integer NOT NULL,
  "sender_member_id" integer NOT NULL,
  "content" text NOT NULL, -- an url
  "message_type" varchar DEFAULT 'TEXT', -- TEXT / IMAGE / FILE...
  "metadata" JSONB,                       -- optional, lưu info file, reaction...
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "edited_at" timestamp,
  "deleted_at" timestamp
);

